function applyBackupRaw(raw){
  if(_rOff||(typeof ARCADE==='object'&&ARCADE&&ARCADE.on)) return;
  var d2=null,back=JSON.stringify(P);
  try{ d2=JSON.parse(raw); }catch(_e){}
